LANGS = ["fr", "es", "it", "de", "ko"]
table = {lang: {} for lang in LANGS}
seen = set()
for row in T:
    en, *rest = row
    assert len(rest) == len(LANGS), row
    assert en not in seen, en
    seen.add(en)
    holes = set(re.findall(r"\{\w+\}", en))
    for lang, text in zip(LANGS, rest):
        assert set(re.findall(r"\{\w+\}", text)) == holes, (lang, en, text)
        if text != en:
            table[lang][en] = text

out = "// The app's texts in other languages, keyed by the English text. {name}\n" \
      "// stands for a part that changes (a number, a place, a Wi-Fi name).\n" \
      "// Made by scripts/make-translations.py; add or change texts there.\n\n" \
      "export const TRANSLATIONS: Record<string, Record<string, string>> = " + json.dumps(table, ensure_ascii=False, indent=2) + ";\n"
open("/home/debian/cakevpn/app/src/translations.ts", "w").write(out)
print(len(T), "texts,", {l: len(v) for l, v in table.items()})
